<style> .wilayah-nav { display:flex; gap:8px; margin-bottom:20px; flex-wrap:wrap; } .wilayah-nav a { padding:8px 16px; background:#e8eaf6; color:#1a73e8; border-radius:6px; text-decoration:none; font-size:14px; font-weight:500; } .wilayah-nav a:hover { background:#c5cae9; } .wilayah-nav a.active { background:#1a73e8; color:#fff; } table { width:100%; border-collapse:collapse; margin-top:12px; } th, td { text-align:left; padding:10px 12px; border-bottom:1px solid #e0e0e0; font-size:14px; } th { background:#f5f5f5; font-weight:600; color:#555; } tr:hover td { background:#fafafa; } .badge { display:inline-block; padding:2px 8px; border-radius:4px; font-size:12px; font-weight:500; } .badge-count { background:#e3f2fd; color:#1565c0; } .btn-sm { padding:4px 12px; border-radius:4px; font-size:12px; text-decoration:none; display:inline-block; margin-right:4px; } .btn-edit { background:#fff3e0; color:#e65100; } .btn-delete { background:#fce4ec; color:#c62828; border:none; cursor:pointer; font-size:12px; padding:4px 12px; border-radius:4px; } .btn-add { display:inline-block; padding:8px 16px; background:#1a73e8; color:#fff; border-radius:6px; text-decoration:none; font-size:14px; font-weight:500; margin-bottom:12px; } .mt-4 { margin-top:24px; } .tab-section { display:none; } .tab-section.active { display:block; } .cascade-select { margin-bottom:16px; } .cascade-select label { font-size:13px; font-weight:500; display:block; margin-bottom:4px; color:#555; } .cascade-select select { width:100%; padding:8px; border:1px solid #d0d0d0; border-radius:6px; font-size:14px; } </style> <h2 style="margin-bottom:16px;">Master Wilayah</h2> <div class="wilayah-nav"> <a href="#" class="active" onclick="showTab('kabupaten');return false;">Kabupaten</a> <a href="#" onclick="showTab('kecamatan');return false;">Kecamatan</a> <a href="#" onclick="showTab('desa');return false;">Desa</a> </div> <!-- Kabupaten --> <div id="tab-kabupaten" class="tab-section active"> <a href="/wilayah/kabupaten/create" class="btn-add">+ Tambah Kabupaten</a> <table> <thead><tr><th>Kode</th><th>Nama Kabupaten</th><th>Aksi</th></tr></thead> <tbody> <?php foreach ($kabupaten as $k): ?> <tr> <td><?= \App\Core\Security::e($k['kode']) ?></td> <td><?= \App\Core\Security::e($k['nama_kabupaten']) ?></td> <td> <a href="/wilayah/kabupaten/edit/<?= (int) $k['id'] ?>" class="btn-sm btn-edit">Edit</a> <form method="POST" action="/wilayah/kabupaten/<?= (int) $k['id'] ?>/delete" style="display:inline" onsubmit="return confirm('Hapus kabupaten ini?')"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn-delete">Hapus</button> </form> </td> </tr> <?php endforeach; ?> <?php if (count($kabupaten) === 0): ?> <tr><td colspan="3" style="text-align:center;color:#999;padding:24px;">Belum ada data kabupaten.</td></tr> <?php endif; ?> </tbody> </table> </div> <!-- Kecamatan --> <div id="tab-kecamatan" class="tab-section"> <a href="/wilayah/kecamatan/create" class="btn-add">+ Tambah Kecamatan</a> <p style="font-size:13px;color:#888;margin-bottom:12px;">Pilih kabupaten untuk memfilter dan mengelola kecamatan.</p> <table id="kecamatan-table"> <thead><tr><th>Kode</th><th>Nama Kecamatan</th><th>Kabupaten</th><th>Aksi</th></tr></thead> <tbody></tbody> </table> <p id="kecamatan-empty" style="text-align:center;color:#999;padding:24px;">Pilih kabupaten untuk menampilkan kecamatan.</p> </div> <!-- Desa --> <div id="tab-desa" class="tab-section"> <a href="/wilayah/desa/create" class="btn-add">+ Tambah Desa</a> <p style="font-size:13px;color:#888;margin-bottom:12px;">Pilih kecamatan untuk memfilter dan mengelola desa.</p> <table id="desa-table"> <thead><tr><th>Kode</th><th>Nama Desa</th><th>Kecamatan</th><th>Kabupaten</th><th>Aksi</th></tr></thead> <tbody></tbody> </table> <p id="desa-empty" style="text-align:center;color:#999;padding:24px;">Pilih kecamatan untuk menampilkan desa.</p> </div> <script> function showTab(name) { document.querySelectorAll('.tab-section').forEach(el => el.classList.remove('active')); document.getElementById('tab-' + name).classList.add('active'); document.querySelectorAll('.wilayah-nav a').forEach(el => el.classList.remove('active')); document.querySelector(`.wilayah-nav a[onclick*="${name}"]`).classList.add('active'); } // Load kecamatan for kabupaten selection (all kabupaten) const kabupatenData = <?= json_encode(array_map(fn($k) => ['id' => (int)$k['id'], 'nama' => $k['nama_kabupaten']], $kabupaten)) ?>; // When kecamatan tab is shown, prompt for kabupaten selection let kecamatanKabupatenId = 0; let desaKecamatanId = 0; // Load kecamatan via API function loadKecamatan(kabupatenId) { kecamatanKabupatenId = kabupatenId; const tbody = document.querySelector('#kecamatan-table tbody'); const empty = document.getElementById('kecamatan-empty'); tbody.innerHTML = ''; if (!kabupatenId) { empty.style.display = 'block'; empty.textContent = 'Pilih kabupaten untuk menampilkan kecamatan.'; return; } fetch('/api/v1/wilayah/kecamatan?kabupaten_id=' + kabupatenId, { headers: { 'Accept': 'application/json' } }) .then(r => r.json()) .then(resp => { const data = resp.data || []; if (data.length === 0) { empty.style.display = 'block'; empty.textContent = 'Belum ada kecamatan di kabupaten ini.'; return; } empty.style.display = 'none'; const kab = kabupatenData.find(k => k.id === kabupatenId); data.forEach(kec => { const tr = document.createElement('tr'); tr.innerHTML = ` <td>${kec.kode}</td> <td>${kec.nama_kecamatan}</td> <td>${kab ? kab.nama : '-'}</td> <td> <a href="/wilayah/kecamatan/edit/${kec.id}" class="btn-sm btn-edit">Edit</a> <form method="POST" action="/wilayah/kecamatan/${kec.id}/delete" style="display:inline" onsubmit="return confirm('Hapus kecamatan ini?')"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn-delete">Hapus</button> </form> </td>`; tbody.appendChild(tr); }); }); } // Load desa via API function loadDesa(kecamatanId) { desaKecamatanId = kecamatanId; const tbody = document.querySelector('#desa-table tbody'); const empty = document.getElementById('desa-empty'); tbody.innerHTML = ''; if (!kecamatanId) { empty.style.display = 'block'; empty.textContent = 'Pilih kecamatan untuk menampilkan desa.'; return; } // First get kecamatan to know kabupaten Promise.all([ fetch('/api/v1/wilayah/desa?kecamatan_id=' + kecamatanId, { headers: { 'Accept': 'application/json' } }).then(r => r.json()), fetch('/api/v1/wilayah/kecamatan/' + kecamatanId, { headers: { 'Accept': 'application/json' } }).then(r => r.json()) ]).then(([desaResp, kecResp]) => { const data = desaResp.data || []; const kecData = kecResp.data || ; if (data.length === 0) { empty.style.display = 'block'; empty.textContent = 'Belum ada desa di kecamatan ini.'; return; } empty.style.display = 'none'; const kab = kabupatenData.find(k => k.id === (kecData.kabupaten_id || 0)); data.forEach(d => { const tr = document.createElement('tr'); tr.innerHTML = ` <td>${d.kode}</td> <td>${d.nama_desa}</td> <td>${kecData.nama_kecamatan || '-'}</td> <td>${kab ? kab.nama : '-'}</td> <td> <a href="/wilayah/desa/edit/${d.id}" class="btn-sm btn-edit">Edit</a> <form method="POST" action="/wilayah/desa/${d.id}/delete" style="display:inline" onsubmit="return confirm('Hapus desa ini?')"> <?= \App\Core\Security::csrfField() ?> <button type="submit" class="btn-delete">Hapus</button> </form> </td>`; tbody.appendChild(tr); }); }); } // Add kabupaten selector to kecamatan and desa tabs document.addEventListener('DOMContentLoaded', function() { const kecTab = document.getElementById('tab-kecamatan'); const desaTab = document.getElementById('tab-desa'); const kecSelector = document.createElement('div'); kecSelector.className = 'cascade-select'; kecSelector.innerHTML = `<label>Pilih Kabupaten</label><select onchange="loadKecamatan(parseInt(this.value)||0)"><option value="">-- Pilih Kabupaten --</option>${kabupatenData.map(k => `<option value="${k.id}">${k.nama}</option>`).join('')}</select>`; kecTab.insertBefore(kecSelector, kecTab.querySelector('table')); const desaSelector = document.createElement('div'); desaSelector.className = 'cascade-select'; desaSelector.innerHTML = `<label>Pilih Kecamatan</label><select id="desa-kecamatan-select" onchange="loadDesa(parseInt(this.value)||0)"><option value="">-- Pilih Kecamatan --</option></select>`; desaTab.insertBefore(desaSelector, desaTab.querySelector('table')); // When kabupaten changes in desa tab, load kecamatan options const desaKabSelect = document.createElement('div'); desaKabSelect.className = 'cascade-select'; desaKabSelect.innerHTML = `<label>Pilih Kabupaten</label><select id="desa-kabupaten-select" onchange="loadDesaKecamatan(parseInt(this.value)||0)"><option value="">-- Pilih Kabupaten --</option>${kabupatenData.map(k => `<option value="${k.id}">${k.nama}</option>`).join('')}</select>`; desaTab.insertBefore(desaKabSelect, desaSelector); }); function loadDesaKecamatan(kabupatenId) { const select = document.getElementById('desa-kecamatan-select'); select.innerHTML = '<option value="">-- Pilih Kecamatan --</option>'; document.querySelector('#desa-table tbody').innerHTML = ''; document.getElementById('desa-empty').style.display = 'block'; document.getElementById('desa-empty').textContent = 'Pilih kecamatan untuk menampilkan desa.'; if (!kabupatenId) return; fetch('/api/v1/wilayah/kecamatan?kabupaten_id=' + kabupatenId, { headers: { 'Accept': 'application/json' } }) .then(r => r.json()) .then(resp => { (resp.data || []).forEach(kec => { const opt = document.createElement('option'); opt.value = kec.id; opt.textContent = kec.nama_kecamatan; select.appendChild(opt); }); }); } </script> 